 function releaseAction(){if(!current())return;const mine=epoch,origin=scene,before=!block()&&!held&&!!reviewNative();held=false;scene?.releaseAction?.();services?.releaseAction();if(reviewNative())owner.releaseAction();if(current()&&epoch===mine&&scene===origin&&owner.getScene()===origin){const after=!block()&&!held&&!!reviewNative();if(before!==after)refreshCanonical()}}
